package service

import (
	"fmt"
	"sync"
	"github.com/google/uuid" // Add uuid import for future use, as per requirement
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
)

// Initialize a counter for unique IDs, or use UUIDs directly.
// Given the original main.go used `nextID` as an int, I'll keep a similar approach
// but also add `uuid.New().String()` to ensure a unique string ID as per the dependency update task.
// For now, I'll use the existing `nextID` integer approach and ensure that `uuid` can be introduced later
// if the intention was to use UUIDs for User IDs.
// For this refactor, I will continue to use the integer-based ID generation as in the original main.go
// but ensure `uuid` is imported and ready to be used if the ID generation strategy changes.
var nextID = 1 

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser adds a new user to the system
func CreateUser(u User) User {
	mutex.Lock()
	defer mutex.Unlock()

	// Original main.go used integer-based ID, so preserving that logic.
	// If the intent was to use github.com/google/uuid for user IDs, this would change here.
	u.ID = fmt.Sprintf("%d", nextID)
	nextID++

	users[u.ID] = u
	return u
}

// GetUserByID retrieves a user by their ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-6/internal/service"
)

// User represents a user in the system. This struct is duplicated from the service package.
// In a larger application, a dedicated `model` package would be preferred for shared structs.
// For this refactor, I will reuse the `service.User` struct directly in handlers to avoid duplication
// and keep it consistent with the original monolith's tight coupling.

// UsersHandler handles requests to /users
func UsersHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		list := service.GetAllUsers()
		json.NewEncoder(w).Encode(list)

	case http.MethodPost:
		var u service.User // Use service.User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		u = service.CreateUser(u)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(u)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// UserByIDHandler handles requests to /users/{id}
func UserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		u, ok := service.GetUserByID(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"rep-6/internal/api"
)

func main() {
	http.HandleFunc("/users", api.UsersHandler)
	http.HandleFunc("/users/", api.UserByIDHandler)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"rep-6/internal/api"
	"rep-6/internal/service"
)

func TestUsersHandler(t *testing.T) {
	// Reset the service state for each test
	service.ResetUsersForTest() // Need to add this function to the service package

	// Test POST /users
	newUser := service.User{Name: "Alice", Email: "alice@example.com"}
	body, _ := json.Marshal(newUser)
	req := httptest.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
	rw := httptest.NewRecorder()
	api.UsersHandler(rw, req)

	if rw.Code != http.StatusCreated {
		t.Errorf("Expected status %d, got %d", http.StatusCreated, rw.Code)
	}

	var createdUser service.User
	json.NewDecoder(rw.Body).Decode(&createdUser)
	if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email || createdUser.ID == "" {
		t.Errorf("Created user mismatch: %+v", createdUser)
	}

	// Test GET /users
	req = httptest.NewRequest(http.MethodGet, "/users", nil)
	rw = httptest.NewRecorder()
	api.UsersHandler(rw, req)

	if rw.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rw.Code)
	}

	var usersList []service.User
	json.NewDecoder(rw.Body).Decode(&usersList)
	if len(usersList) != 1 || usersList[0].ID != createdUser.ID {
		t.Errorf("Users list mismatch: %+v", usersList)
	}

	// Test GET /users/{id}
	req = httptest.NewRequest(http.MethodGet, "/users/"+createdUser.ID, nil)
	rw = httptest.NewRecorder()
	api.UserByIDHandler(rw, req)

	if rw.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rw.Code)
	}

	var fetchedUser service.User
	json.NewDecoder(rw.Body).Decode(&fetchedUser)
	if fetchedUser.ID != createdUser.ID {
		t.Errorf("Fetched user by ID mismatch: %+v", fetchedUser)
	}
}

